/// <summary>
/// Continuing permission notice report controller
/// Class <c>METPOContinuingPermissionNoticeController</c> controller
/// </summary>
class METPOContinuingPermissionNoticeController extends SrsReportRunController
{
}

Method.Source:
/// <summary>
/// constructor creates the instance for class
/// </summary>
/// <returns>constructor</returns>
public static METPOContinuingPermissionNoticeController construct()
{
    return new METPOContinuingPermissionNoticeController();
}

/// <summary>
/// Main method to run report
/// </summary>
/// <param name = "_args">_args</param>
static void main(Args _args)
{
    METPOContinuingPermissionNoticeController controller =
        METPOContinuingPermissionNoticeController::construct();

    //controller.parmReportName(ssrsReportStr(METPOContinuingPermissionNotice, CPReport));

    PrintMgmtReportFormat printMgmtReportFormat = PrintMgmtReportFormat::findSystem(PrintMgmtDocumentType::METPOContinuingPermissionNote);
    controller.parmReportName(printMgmtReportFormat.Name);
    METPOContinuingPermissionNoticeContract contract = controller.parmReportContract().parmRdpContract() as METPOContinuingPermissionNoticeContract;
    VendInvoiceJour vendInvoiceJour = _args.record();
    contract.parmPurchId(vendInvoiceJour.PurchId);
    contract.parmInvJourRecId(vendInvoiceJour.RecId);

    if (_args.menuItemName() == menuItemOutputStr(METPOContinuingPermissionNotice))
    {
        contract.parmIsRePrint(true);
    }
    else
    {
        contract.parmIsRePrint(false);
    }

    controller.parmReportContract().parmRdpContract(contract);
    controller.parmArgs(_args);
    controller.parmShowDialog(false);
    controller.parmDialogCaption("@MET:METCPNotice");
    controller.startOperation();
}
